package pk.edu.dsu.scd;import org.junit.jupiter.api.Test;import pk.edu.dsu.scd.lab10.strategy.*;import pk.edu.dsu.scd.lab10.observer.*;import pk.edu.dsu.scd.lab11.*;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;class Lab10And11Test{@Test void strategy(){assertEquals(9000,new DiscountContext(new BulkDiscount()).calculate(10000),.001);}@Test void observer(){OrderObserver o=mock(OrderObserver.class);OrderPublisher p=new OrderPublisher();p.subscribe(o);p.publish("ORD-1");verify(o).onOrderCreated("ORD-1");}@Test void safeCounter()throws Exception{SafeCounter c=new SafeCounter();Thread a=new Thread(()->{for(int i=0;i<1000;i++)c.increment();});Thread b=new Thread(()->{for(int i=0;i<1000;i++)c.increment();});a.start();b.start();a.join();b.join();assertEquals(2000,c.get());}}